 const openSavedChart=async(chart:SavedChart, selectedDifficulty:Difficulty=chart.difficulty)=>{if(supabase)supabase.rpc('increment_chart_play',{p_chart_id:chart.id}).then(()=>{});const source=(chart.notes||[]).map((n,i)=>({...n,id:i,hit:false,miss:false,holding:false,completed:false}));if(audio.current){audio.current.pause();audio.current.currentTime=0}if(urlRef.current){URL.revokeObjectURL(urlRef.current);urlRef.current=null}setAudioUrl(null);fileRef.current=null;setSongName(chart.title);setActiveInstrument(chart.instrument||'mix');setDifficulty(selectedDifficulty);setLaneCount(chart.lane_count);setDuration(chart.duration);setBaseNotes(source);setNotes(buildChart(source,chart.lane_count,selectedDifficulty));setMyChartsOpen(false);setDiscoverOpen(false);setDuplicateOpen(false);setActiveChartId(chart.id);await loadLeaderboard(chart.id,selectedDifficulty);const cached=await recallAudio(chart.id);if(cached){const url=URL.createObjectURL(cached);urlRef.current=url;fileRef.current=cached;setAudioUrl(url);try{const arr=await cached.arrayBuffer();const ctx=new AudioContext();const buffer=await ctx.decodeAudioData(arr.slice(0));setDuration(buffer.duration);await ctx.close()}catch{}setStatus('Community chart + saved local audio ready')}else if(chart.youtube_url&&youtubeId(chart.youtube_url)){setPendingChart(chart);setAudioNeededOpen(false);setStatus('Community chart + YouTube ready · start the video, then press PLAY')}else{setPendingChart(chart);setAudioNeededOpen(true);setStatus('Community chart loaded · audio required')}};
